    bg=Counter(x for r in I for x in r).most_common(1)[0][0]
    gds=[list(g) for g in comps_of(I,bg) if len(g)>1]
    allc=set().union(*gds)
    singles=[(a,b,I[a][b]) for a in range(h) for b in range(w) if (a,b) not in allc and I[a][b]!=bg]
    out=[[v for v in row] for row in I]
    for mr,mc,v in singles:
        best=None
        for gi,g in enumerate(gds):
            cnt=Counter(I[r][c] for r,c in g)
            for av,aw in g:
                if I[av][aw]==v:
                    off=(mr-av,mc-aw)
                    ok=all(0<=off[0]+x<h and 0<=off[1]+y<w for x,y in g)
                    if ok:
                        # coverage score: how many background cells it covers
                        cov=sum(1 for x,y in g if 0<=off[0]+x<h and 0<=off[1]+y<w and I[off[0]+x][off[1]+y]==bg)
                        if best is None or cov>best[0]: best=(cov,gi,off)
        if best:
            _,gi,(o0,o1)=best
            for x,y in gds[gi]:
                p,q=o0+x,o1+y
                if 0<=p<h and 0<=q<w and I[p][q]==bg: out[p][q]=I[x][y]
    return out
