def variants(sq):
    out=[]
    cur=[list(r) for r in sq]; h=len(cur); w=len(cur[0])
    for _ in range(4):
        for fl in (False,True):
            m=[[cur[w-1-j][i] for j in range(w)] for i in range(h)] if fl else [[cur[i][j] for j in range(w)] for i in range(h)]
            out.append(m)
        cur=[[cur[j][w-1-i] for j in range(w)] for i in range(h)]
    # dedupe by content
    seen=set(); uniq=[]
    for m in out:
        key=tuple(tuple(row) for row in m)
        if key not in seen: seen.add(key); uniq.append(m)
    return uniq

def solve(d):
    I=G[f'Demo pair {d} input']; O=G[f'Demo pair {d} output']
    h,w=len(I),len(I[0])
    bg=C2(x for r in I for x in r).most_common(1)[0][0]
    objs=[]
    for g in comps_of(I,bg):
        if len(g)>1: objs.append(set(g))
    alltmpl=set().union(*objs)
    singles=sorted([(a,b,I[a][b]) for a in range(h) for b in range(w) if (a,b) not in alltmpl and I[a][b]!=bg])
    results={}
    for mr,mc,v in singles:
        found=[]
        for ti,obj in enumerate(objs):
            tcol=C2(I[r][c] for r,c in obj).most_common(1)[0][0]
            acc=[(r,c) for r,c in obj if I[r][c]!=tcol]
            for var in variants([[(r,c) for r,c in obj]]):
                pass
            # simpler: use offset such that accent cell (any cell of non-majority color) lands on marker
            for ar,ac in acc:
                off=(mr-ar,mc-ac)
                paint={(off[0]+r,off[1]+c) for r,c in obj}
                ok=True
                for p,q in paint:
                    if not(0<=p<h and 0<=q<w) or (p,q)==(mr,mc): continue
                    if I[p][q]==bg and O[p][q]!=I[ar][ac]: ok=False;break
                    if I[p][q]!=bg: ok=False;break
                if not ok: continue
                # must cover all added cells
                added={(p,q) for p in range(h) for q in range(w) if I[p][q]==bg and O[p][q]!=bg}-{(mr,mc)} if False else {(p,q) for p in range(h) for q in range(w) if I[p][q]==bg and O[p][q]!=bg}
                if paint>=added and paint<=added|{(mr,mc)}:
                    found.append((ti,'acc',(ar,ac),off,paint==added))
        if not found:
            print('NO EXACT for',mr,mc,v); continue
        best=max(found,key=lambda z:len(z[4]))
        results[(mr,mc,v)]=(best[0],best[1],best[2],best[3],best[4])
    return results
