            while st:
                cur=st.pop()
                for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                    n=(cur[0]+dr,cur[1]+dc)
                    if 0<=n[0]<h and 0<=n[1]<w and I[n[0]][n[1]]!=bg and n not in seen:
                        seen.add(n); st.append(n); comp.append(n)
            if len(comp)>1: objs.append((comp,[I[r][c] for r,c in comp]))
    marks=[(i,j,I[i][j]) for i in range(h) for j in range(w) if I[i][j]!=bg and (i,j) not in {c for o,colors in objs for c in o}]
