from collections import deque
def comps_of(g,bg):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; out=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]!=bg and not seen[i][j]:
                st=[(i,j)]; seen[i][j]=True; cells=[]
                while st:
                    y,x=st.pop(); cells.append((y,x))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            ny,nx=y+dy,x+dx
                            if 0<=ny<H and 0<=nx<W and not seen[ny][nx] and g[ny][nx]==g[y][x]:
                                seen[ny][nx]=True; st.append((ny,nx))
                out.append(cells)
    return out
def solve(g):
    H,W=len(g),len(g[0])
    # background = most common
    cnt=Counter(v for r in g for v in r); bg=cnt.most_common(1)[0][0]
    cs=comps_of(g,bg)
    big=max(cs,key=len)
    small=[c for c in cs if c is not big]
    tmpl=[(r-min(x for x,y in big),c-min(y for y,x in big)) for r,c in big]
    res=[row[:] for row in g]
    for cells in small:
        (ry,cy),(r2,c2)=cells[0],cells[-1]
        for dr,dc in tmpl:
            rr,cc=ry+dr,cy+dc
            if 0<=rr<H and 0<=cc<W:
                res[rr][cc]=g[r2][c2]
    return res
