import os,glob,re,json
d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
base=d+'/../../sessions/'
# Find any session with demo pairs for the same recurring task id (task appears fresh per instance but may repeat)
for f in sorted(glob.glob(base+'*.jsonl')):
    t=open(f,errors='ignore').read().replace('\\n','\n')
    if re.search(r'task-[0-9a-f]{10}',t):
        ids=set(re.findall(r'task-[0-9a-f]{10}',t))
        n=sum(1 for m in re.finditer(r'Demo pair \d+ input \(\d+x\d+\):\n',t))
        if ids and n: print('==',f.split('/')[-1][:8],'ids:',sorted(ids),'demos:',n)

import os,glob,re,json
d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n')
G={}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
    k,h,w=m[1],int(m[2]),int(m[3])
    rows=[r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
        G[k]=[[int(x) for x in r] for r in rows]
print(sorted(G))
